/**
 * One sign-in attempt, discriminated by the surface the app rendered. SSO carries no credentials;
 * the other two carry what the user typed.
 *
 * `returnTo` is the root-relative path to land on afterwards — typically the one the gate put on the
 * login url. It is normalised before it is sent, so an off-origin value falls back to the app root.
 */
type LoginFlow = {
    type: 'sso';
    identityProviderId: string;
    returnTo?: string;
} | {
    type: 'password';
    identityProviderId: string;
    returnTo?: string;
    username: string;
    password: string;
} | {
    type: 'otp';
    identityProviderId: string;
    returnTo?: string;
    username: string;
};
/**
 * Sign in against one identity provider — SSO, username+password, or OTP — and hand back the
 * `redirectUrl` to send the browser to. The caller navigates.
 *
 * The companion to `useIdentityProviders`: that lists an app's providers, this signs in with the
 * one the user picked. Every flow goes through the `/auth/workflow/execute/node` login data sources,
 * which is what the platform's own login page and every matrix app already do.
 *
 * Why not `POST /auth/login` (what `useAuthLogin` calls): that route forces `returnTo` to a relative
 * path. The credential flows survive it — they never leave the page, so the browser resolves the
 * path against the app itself. SSO does not: the platform keeps the value through the round trip and
 * replays it as a Location header, where a relative path resolves against the auth service and drops
 * the user on `<app>/auth/` looking at a raw error payload.
 *
 * Blocked in the builder preview along with the other auth calls (see previewAuth): the preview
 * shares the maker's platform session, and signing in would replace it.
 */
declare function useIdentityProviderLogin(options?: {
    mutation?: UseMutationOptions<LoginNodeResponse, ErrorType<unknown>, LoginFlow>;
}): UseMutationResult<LoginNodeResponse, ErrorType<unknown>, LoginFlow>;

